import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# packet.BlockPickRequest{Position: protocol.BlockPos{1, -2, 300}, AddBlockNBT: true, HotBarSlot: 200}
WITH_DATA = bytes.fromhex("0203d80401c8")

# generated by gophertunnel b8bd735:
# packet.BlockPickRequest{Position: protocol.BlockPos{0, -1, 0}, AddBlockNBT: false, HotBarSlot: 0}
NEGATIVE = bytes.fromhex("0001000000")

GOLDENS = [
    pytest.param(
        v2225.BlockPickRequestPacket(pos=v2225.BlockPos(x=1, y=-2, z=300), with_data=True, max_slots=200),
        WITH_DATA,
        id="with-data",
    ),
    pytest.param(
        v2225.BlockPickRequestPacket(pos=v2225.BlockPos(x=0, y=-1, z=0), with_data=False, max_slots=0),
        NEGATIVE,
        id="negative-coordinate",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225])
def test_block_pick_request_is_packet_34(version):
    assert version.packets[34] is version.BlockPickRequestPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_block_pick_request_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_block_pick_request_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


def test_block_pick_request_rejects_a_body_missing_the_slot_byte():
    with pytest.raises(ValueError, match="at byte"):
        v2225.BlockPickRequestPacket.from_bytes(WITH_DATA[:-1])
